def _render_svg_pixmap(svg_template: str, color: QColor, size: int = 24, fallback_kind: str = "playlist") -> QPixmap:
    scale = 2
    px = size * scale
    pix = QPixmap(px, px)
    pix.fill(Qt.GlobalColor.transparent)
    p = QPainter(pix)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)

    if HAS_QTSVG:
        svg_str = svg_template.format(color=color.name())
        renderer = QSvgRenderer(QByteArray(svg_str.encode("utf-8")))
        renderer.render(p, QRectF(0, 0, px, px))
    else:
        pen = QPen(color, px * 0.08)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        if fallback_kind == "artist":
            p.drawEllipse(QRectF(px * 0.32, px * 0.16, px * 0.36, px * 0.36))
            p.drawArc(QRectF(px * 0.18, px * 0.56, px * 0.64, px * 0.50), 0, 180 * 16)
        elif fallback_kind == "search":
            p.drawEllipse(QRectF(px * 0.18, px * 0.18, px * 0.46, px * 0.46))
            p.drawLine(QPointF(px * 0.58, px * 0.58), QPointF(px * 0.82, px * 0.82))
        elif fallback_kind == "refresh":
            p.drawArc(QRectF(px * 0.18, px * 0.18, px * 0.64, px * 0.64), 45 * 16, 270 * 16)
            p.drawLine(QPointF(px * 0.60, px * 0.15), QPointF(px * 0.75, px * 0.30))
            p.drawLine(QPointF(px * 0.90, px * 0.15), QPointF(px * 0.75, px * 0.30))
        elif fallback_kind == "settings":
            p.drawEllipse(QRectF(px * 0.22, px * 0.22, px * 0.56, px * 0.56))
            p.drawEllipse(QRectF(px * 0.38, px * 0.38, px * 0.24, px * 0.24))
        elif fallback_kind == "folder":
            p.drawPolygon(QPolygonF([
                QPointF(px * 0.14, px * 0.24), QPointF(px * 0.46, px * 0.24),
                QPointF(px * 0.52, px * 0.34), QPointF(px * 0.86, px * 0.34),
                QPointF(px * 0.86, px * 0.78), QPointF(px * 0.14, px * 0.78),
            ]))
        elif fallback_kind == "fire":
            p.drawPolygon(QPolygonF([
                QPointF(px * 0.50, px * 0.18), QPointF(px * 0.66, px * 0.38),
                QPointF(px * 0.60, px * 0.52), QPointF(px * 0.78, px * 0.56),
                QPointF(px * 0.72, px * 0.78), QPointF(px * 0.50, px * 0.88),
                QPointF(px * 0.28, px * 0.78), QPointF(px * 0.22, px * 0.56),
                QPointF(px * 0.40, px * 0.52), QPointF(px * 0.34, px * 0.38),
            ]))
        elif fallback_kind == "favorites":
            p.drawArc(QRectF(px * 0.18, px * 0.20, px * 0.32, px * 0.32), 0, 180 * 16)
            p.drawArc(QRectF(px * 0.50, px * 0.20, px * 0.32, px * 0.32), 0, 180 * 16)
            p.drawPolyline(QPolygonF([
                QPointF(px * 0.18, px * 0.36), QPointF(px * 0.50, px * 0.82),
                QPointF(px * 0.82, px * 0.36),
            ]))
        elif fallback_kind == "songs":
            for sx in (0.34, 0.76):
                p.drawLine(QPointF(px * sx, px * 0.28), QPointF(px * sx, px * 0.70))
            p.drawLine(QPointF(px * 0.34, px * 0.28), QPointF(px * 0.76, px * 0.20))
            p.drawEllipse(QRectF(px * 0.22, px * 0.62, px * 0.24, px * 0.16))
            p.drawEllipse(QRectF(px * 0.64, px * 0.54, px * 0.24, px * 0.16))
        elif fallback_kind == "home":
            p.drawPolyline(QPolygonF([
                QPointF(px * 0.14, px * 0.48), QPointF(px * 0.5, px * 0.18),
                QPointF(px * 0.86, px * 0.48),
            ]))
            p.drawPolyline(QPolygonF([
                QPointF(px * 0.24, px * 0.44), QPointF(px * 0.24, px * 0.82),
                QPointF(px * 0.76, px * 0.82), QPointF(px * 0.76, px * 0.44),
            ]))
        elif fallback_kind == "album":
            for r in (0.42, 0.32, 0.22, 0.12):
                p.drawEllipse(QRectF(px * (0.5 - r), px * (0.5 - r), px * (r * 2), px * (r * 2)))
        else:
            for y in (0.25, 0.45, 0.65):
                p.drawLine(QPointF(px * 0.15, px * y), QPointF(px * 0.58, px * y))
            p.drawEllipse(QRectF(px * 0.48, px * 0.62, px * 0.24, px * 0.20))
            p.drawLine(QPointF(px * 0.72, px * 0.72), QPointF(px * 0.72, px * 0.20))

    p.end()
    pix.setDevicePixelRatio(scale)
    return pix

