_FAVORITE_ICON_CACHE = {}

def get_favorite_icon(color: QColor = None, size: int = 16) -> QIcon:
    if color is None:
        color = QApplication.palette().color(QPalette.ColorRole.Highlight)
    key = (color.name(), size)
    icon = _FAVORITE_ICON_CACHE.get(key)
    if icon is None:
        icon = make_favorites_icon(color, size)
        _FAVORITE_ICON_CACHE[key] = icon
    return icon

def format_time(ms):
    seconds = max(0, (ms or 0) // 1000)
    mins, secs = divmod(seconds, 60)
    return f"{mins:02d}:{secs:02d}"

MEDIA_ICONS_SVG = Path(__file__).resolve().parent.parent / "resources" / "media_buttons.svg"
MEDIA_ICON_VIEWBOXES = {
    "play": QRectF(2192, 2472, 616, 616),
    "pause": QRectF(2192, 1412, 616, 616),
    "prev": QRectF(2880, 2472, 616, 616),
    "next": QRectF(3567, 2472, 616, 616),
    "repeat": QRectF(817, 2472, 616, 616),
    "volume": QRectF(1505, 2472, 616, 616),
}
_media_sheet_renderer = None

def _render_media_sheet_icon(kind: str, color: QColor, size: int):
    """Ambil satu tombol dari lembar ikon media player (resources/media_buttons.svg)."""
    global _media_sheet_renderer
    viewbox = MEDIA_ICON_VIEWBOXES.get(kind)
    if viewbox is None or not HAS_QTSVG or not MEDIA_ICONS_SVG.exists():
        return None
    if _media_sheet_renderer is None:
        _media_sheet_renderer = QSvgRenderer(str(MEDIA_ICONS_SVG))
    if not _media_sheet_renderer.isValid():
        return None

    scale = 3
    px = size * scale
    pix = QPixmap(px, px)
    pix.fill(Qt.GlobalColor.transparent)

    painter = QPainter(pix)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    _media_sheet_renderer.setViewBox(viewbox)
    _media_sheet_renderer.render(painter, QRectF(0, 0, px, px))
    painter.end()

    # Warnai ulang ikon hitam dari file sesuai warna tema
    painter = QPainter(pix)
    painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceIn)
    painter.fillRect(pix.rect(), color)
    painter.end()
    return pix

def make_media_icon(kind: str, color: QColor, size: int = 38) -> QIcon:
    sheet_kind = "volume" if kind == "mute" else ("repeat" if kind == "repeat_one" else kind)
    sheet_pix = _render_media_sheet_icon(sheet_kind, color, size)
    if sheet_pix is not None:
        px = sheet_pix.width()
        p = QPainter(sheet_pix)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        if kind == "mute":
            # Ganti gelombang suara (kiri ikon) dengan tanda X
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Source)
            p.fillRect(QRectF(px * 0.15, px * 0.27, px * 0.31, px * 0.46),
                       Qt.GlobalColor.transparent)
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
            pen = QPen(color, px * 0.065)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            p.drawLine(QPointF(px * 0.20, px * 0.40), QPointF(px * 0.40, px * 0.60))
            p.drawLine(QPointF(px * 0.40, px * 0.40), QPointF(px * 0.20, px * 0.60))
        elif kind == "repeat_one":
            font = p.font()
            font.setBold(True)
            font.setPixelSize(int(px * 0.30))
            p.setFont(font)
            p.setPen(color)
            p.drawText(sheet_pix.rect(), Qt.AlignmentFlag.AlignCenter, "1")
        p.end()
        sheet_pix.setDevicePixelRatio(sheet_pix.width() / size)
        return QIcon(sheet_pix)

    scale = 2
    px = size * scale
    pix = QPixmap(px, px)
    pix.fill(Qt.GlobalColor.transparent)

    p = QPainter(pix)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.scale(px / 100.0, px / 100.0)

    ring_pen = QPen(color, 4.8)
    ring_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    ring_pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)

    p.setPen(ring_pen)
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.drawEllipse(QRectF(7, 7, 86, 86))

    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(color)

    if kind == "play":
        p.drawPolygon(QPolygonF([QPointF(40, 30), QPointF(40, 70), QPointF(72, 50)]))
    elif kind == "pause":
        p.drawRoundedRect(QRectF(36, 30, 9.5, 40), 2, 2)
        p.drawRoundedRect(QRectF(54.5, 30, 9.5, 40), 2, 2)
    elif kind == "prev":
        p.drawRoundedRect(QRectF(28, 32, 7.5, 36), 1.5, 1.5)
        p.drawPolygon(QPolygonF([QPointF(68, 31), QPointF(68, 69), QPointF(38, 50)]))
    elif kind == "next":
        p.drawPolygon(QPolygonF([QPointF(32, 31), QPointF(32, 69), QPointF(62, 50)]))
        p.drawRoundedRect(QRectF(64.5, 32, 7.5, 36), 1.5, 1.5)
    elif kind in ("repeat", "repeat_one"):
        line_pen = QPen(color, 5.0)
        line_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        line_pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        p.setPen(line_pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPolyline(QPolygonF([QPointF(28, 46), QPointF(28, 35), QPointF(64, 35)]))
        p.drawPolyline(QPolygonF([QPointF(72, 54), QPointF(72, 65), QPointF(36, 65)]))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(color)
        p.drawPolygon(QPolygonF([QPointF(62, 26), QPointF(62, 44), QPointF(75, 35)]))
        p.drawPolygon(QPolygonF([QPointF(38, 56), QPointF(38, 74), QPointF(25, 65)]))
        if kind == "repeat_one":
            font = p.font()
            font.setBold(True)
            font.setPointSize(20)
            p.setFont(font)
            p.setPen(color)
            p.drawText(QRectF(32, 34, 36, 32), Qt.AlignmentFlag.AlignCenter, "1")
    elif kind == "shuffle":
        line_pen = QPen(color, 5.0)
        line_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        line_pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        p.setPen(line_pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPolyline(QPolygonF([QPointF(26, 63), QPointF(42, 63), QPointF(58, 37), QPointF(67, 37)]))
        p.drawPolyline(QPolygonF([QPointF(26, 37), QPointF(42, 37), QPointF(58, 63), QPointF(67, 63)]))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(color)
        p.drawPolygon(QPolygonF([QPointF(65, 29), QPointF(65, 45), QPointF(77, 37)]))
        p.drawPolygon(QPolygonF([QPointF(65, 55), QPointF(65, 71), QPointF(77, 63)]))
    elif kind == "volume":
        p.drawPolygon(QPolygonF([
            QPointF(26, 42), QPointF(37, 42), QPointF(50, 30),
            QPointF(50, 70), QPointF(37, 58), QPointF(26, 58)
        ]))
        wave_pen = QPen(color, 4.8)
        wave_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(wave_pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawArc(QRectF(45, 38, 18, 24), -55 * 16, 110 * 16)
        p.drawArc(QRectF(45, 30, 29, 40), -55 * 16, 110 * 16)
    elif kind == "mute":
        p.drawPolygon(QPolygonF([
            QPointF(26, 42), QPointF(37, 42), QPointF(50, 30),
            QPointF(50, 70), QPointF(37, 58), QPointF(26, 58)
        ]))
        x_pen = QPen(color, 5.2)
        x_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(x_pen)
        p.drawLine(QPointF(59, 41), QPointF(73, 59))
        p.drawLine(QPointF(73, 41), QPointF(59, 59))
    elif kind == "expand":
        b_pen = QPen(color, 5.0)
        b_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        b_pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        p.setPen(b_pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPolyline(QPolygonF([QPointF(32, 43), QPointF(32, 32), QPointF(43, 32)]))
        p.drawPolyline(QPolygonF([QPointF(57, 32), QPointF(68, 32), QPointF(68, 43)]))
        p.drawPolyline(QPolygonF([QPointF(32, 57), QPointF(32, 68), QPointF(43, 68)]))
        p.drawPolyline(QPolygonF([QPointF(57, 68), QPointF(68, 68), QPointF(68, 57)]))

    p.end()
    pix.setDevicePixelRatio(scale)
    return QIcon(pix)

def round_pixmap(pixmap: QPixmap, size: int, radius: int = 12) -> QPixmap:
    if pixmap.isNull():
        return pixmap
    scaled = pixmap.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
    if scaled.width() > size or scaled.height() > size:
        x = (scaled.width() - size) // 2
        y = (scaled.height() - size) // 2
        scaled = scaled.copy(x, y, size, size)
    out = QPixmap(size, size)
    out.fill(Qt.GlobalColor.transparent)
    painter = QPainter(out)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    path = QPainterPath()
    path.addRoundedRect(0, 0, size, size, radius, radius)
    painter.setClipPath(path)
    painter.drawPixmap(0, 0, scaled)
    painter.end()
    return out

def generate_fallback_cover(size=100, radius=12):
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)

    path = QPainterPath()
    path.addRoundedRect(0, 0, size, size, radius, radius)
    painter.setClipPath(path)
    painter.fillRect(0, 0, size, size, QColor(34, 34, 34))

    m = int(size * 0.1)
    painter.setBrush(QColor(22, 22, 22))
    painter.setPen(QColor(55, 55, 55))
    painter.drawEllipse(m, m, size - 2 * m, size - 2 * m)

    m_lbl = int(size * 0.36)
    painter.setBrush(QColor(135, 186, 120))
    painter.setPen(Qt.PenStyle.NoPen)
    painter.drawEllipse(m_lbl, m_lbl, size - 2 * m_lbl, size - 2 * m_lbl)

    m_hole = int(size * 0.46)
    painter.setBrush(QColor(24, 24, 24))
    painter.drawEllipse(m_hole, m_hole, size - 2 * m_hole, size - 2 * m_hole)
    painter.end()
    return pixmap

def generate_playlist_badge(name: str, size=42, symbol: str = "") -> QPixmap:
    colors = ["#e91e63", "#87ab63", "#3fa3b4", "#417db7", "#e48a3c", "#905bb6", "#2ea586"]
    idx = sum(ord(c) for c in name) % len(colors)
    pix = QPixmap(size, size)
    pix.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pix)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)

    path = QPainterPath()
    path.addRoundedRect(0, 0, size, size, 10, 10)
    painter.setClipPath(path)
    painter.fillRect(0, 0, size, size, QColor(colors[idx]))

    if symbol == "♥":
        icon_size = int(size * 0.62)
        svg_pix = render_favorites_svg_pixmap(QColor(255, 255, 255), icon_size)
        offset = (size - icon_size) // 2
        painter.drawPixmap(offset, offset, svg_pix)
    elif symbol == "fire":
        icon_size = int(size * 0.62)
        svg_pix = render_fire_svg_pixmap(QColor(255, 255, 255), icon_size)
        offset = (size - icon_size) // 2
        painter.drawPixmap(offset, offset, svg_pix)
    elif symbol == "★":
        painter.setPen(QColor(255, 255, 255))
        font = painter.font()
        font.setBold(True)
        font.setPointSize(max(12, int(size * 0.38)))
        painter.setFont(font)
        painter.drawText(pix.rect(), Qt.AlignmentFlag.AlignCenter, symbol)
    else:
        icon_size = int(size * 0.62)
        svg_pix = render_playlist_svg_pixmap(QColor(255, 255, 255), icon_size)
        offset = (size - icon_size) // 2
        painter.drawPixmap(offset, offset, svg_pix)

    painter.end()
    return pix

def get_cover_art(filepath):
    try:
        audio = mutagen.File(filepath)
        if audio and hasattr(audio, 'pictures') and audio.pictures:
            return audio.pictures[0].data
        if audio and hasattr(audio, 'tags') and audio.tags:
            for key, val in audio.tags.items():
                if key.startswith('APIC'):
                    return val.data
    except Exception:
        pass

    try:
        folder = os.path.dirname(filepath)
        for fname in ('cover.jpg', 'cover.png', 'folder.jpg', 'folder.png',
                      'albumart.jpg', 'albumart.png', 'front.jpg', 'front.png'):
            ext_path = os.path.join(folder, fname)
            if os.path.exists(ext_path):
                with open(ext_path, 'rb') as f:
                    return f.read()
    except Exception:
        pass
    return None

def get_cached_cover_pixmap(filepath, size=260, radius=12):
    try:
        key = hashlib.md5(filepath.encode('utf-8')).hexdigest()
        cache_path = CACHE_ARTWORK_DIR / f"{key}.png"
        if cache_path.exists():
            pix = QPixmap(str(cache_path))
            if not pix.isNull():
                return round_pixmap(pix, size, radius)

        cover_data = get_cover_art(filepath)
        if cover_data:
            img = QImage.fromData(cover_data)
            if not img.isNull():
                scaled_img = img.scaled(300, 300, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
                CACHE_ARTWORK_DIR.mkdir(parents=True, exist_ok=True)
                scaled_img.save(str(cache_path), "PNG")
                return round_pixmap(QPixmap.fromImage(scaled_img), size, radius)
    except Exception as e:
        logger.warning(f"Gagal memproses cover art {filepath}: {e}")
    return None

def get_dominant_color(pixmap: QPixmap) -> QColor:
    if pixmap.isNull():
        return QColor(50, 50, 50)
    img = pixmap.toImage().scaled(1, 1, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
    return img.pixelColor(0, 0)

def get_audio_tech_summary(filepath):
    codec = os.path.splitext(filepath)[1].upper().replace(".", "")
    parts = [codec] if codec else []
    try:
        audio = mutagen.File(filepath)
        if audio and hasattr(audio, 'info'):
            info = audio.info
            if hasattr(info, 'sample_rate') and info.sample_rate:
                parts.append(f"{info.sample_rate / 1000:.1f} kHz")
            if hasattr(info, 'bitrate') and info.bitrate:
                parts.append(f"{round(info.bitrate / 1000)} kbps")
    except Exception:
        pass
    return " • ".join(parts)

class TrackInfoDialog(QDialog):
    def __init__(self, track, parent=None):
        super().__init__(parent)
        self.setWindowTitle("ℹ️ Rincian Informasi Lagu")
        self.resize(480, 320)
        layout = QVBoxLayout(self)
        form = QFormLayout()
        
        bitrate_str, sample_rate_str = "-", "-"
        codec_str = os.path.splitext(track['path'])[1].upper().replace(".", "")
        try:
            audio = mutagen.File(track['path'])
            if audio and hasattr(audio, 'info'):
                info = audio.info
                if hasattr(info, 'bitrate') and info.bitrate:
                    bitrate_str = f"{round(info.bitrate / 1000)} kbps"
                if hasattr(info, 'sample_rate') and info.sample_rate:
                    sample_rate_str = f"{info.sample_rate} Hz"
        except Exception:
            pass

        file_size_mb = f"{os.path.getsize(track['path']) / (1024 * 1024):.2f} MB" if os.path.exists(track['path']) else "-"
        form.addRow("Judul:", QLabel(track.get('title') or "-"))
        form.addRow("Artis:", QLabel(track.get('artist') or "-"))
        form.addRow("Album:", QLabel(track.get('album') or "-"))
        form.addRow("Durasi:", QLabel(format_time(track.get('duration_ms') or 0)))
        form.addRow("Jumlah Diputar:", QLabel(f"{track.get('play_count') or 0} kali"))
        form.addRow("Format Codec:", QLabel(codec_str))
        form.addRow("Bitrate:", QLabel(bitrate_str))
        form.addRow("Sample Rate:", QLabel(sample_rate_str))
        form.addRow("Ukuran File:", QLabel(file_size_mb))
        
        lbl_path = QLabel(track['path'])
        lbl_path.setWordWrap(True)
        lbl_path.setStyleSheet("font-size: 11px;")
        form.addRow("Lokasi File:", lbl_path)
        
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        buttons.rejected.connect(self.reject)
        layout.addLayout(form)
        layout.addWidget(buttons)

class TrackTableModel(QAbstractTableModel):
    def __init__(self, data):
        super().__init__()
        self._data = data
        self.headers = ["#", "Judul", "Artis", "Album", "Diputar", "Durasi", "Fav"]

    def rowCount(self, parent=QModelIndex()): return len(self._data)
    def columnCount(self, parent=QModelIndex()): return len(self.headers)

    def data(self, index, role=Qt.ItemDataRole.DisplayRole):
        track = self._data[index.row()]
        col = index.column()
        if role == Qt.ItemDataRole.DisplayRole:
            if col == 0: return index.row() + 1
            elif col == 1: return track['title']
            elif col == 2: return track['artist']
            elif col == 3: return track['album']
            elif col == 4: return track.get('play_count') or 0
            elif col == 5: return format_time(track.get('duration_ms') or 0)
            elif col == 6: return ""
        elif role == Qt.ItemDataRole.DecorationRole:
            if col == 6 and (track.get('rating') or 0) > 0:
                return get_favorite_icon(size=16)
        elif role == Qt.ItemDataRole.TextAlignmentRole:
            if col in (0, 4, 5, 6):
                return Qt.AlignmentFlag.AlignCenter
        return QVariant()

    def headerData(self, section, orientation, role=Qt.ItemDataRole.DisplayRole):
        if role == Qt.ItemDataRole.DisplayRole and orientation == Qt.Orientation.Horizontal:
            return self.headers[section]
        return QVariant()

