    def set_track_info(self, title, artist, duration_ms, pixmap: QPixmap):
        self.lbl_title.setText(title)
        self.lbl_artist.setText(artist)
        self.total_ms = duration_ms or 0
        self.slider.setRange(0, self.total_ms)
        self.lbl_dur.setText(format_time(self.total_ms))
        self.lbl_pos.setText("00:00")
        if pixmap and not pixmap.isNull():
            self.lbl_cover.setPixmap(round_pixmap(pixmap, 300, 18))
            self.ambient_color = get_dominant_color(pixmap)
        else:
            self.lbl_cover.setPixmap(generate_fallback_cover(300, 18))
            self.ambient_color = QColor(52, 58, 50)
        self.update()

    def update_position(self, ms):
        if not self.slider.isSliderDown():
            self.slider.setValue(ms)
            self.lbl_pos.setText(format_time(ms))

    def paintEvent(self, event):
        painter = QPainter(self)
        grad = QLinearGradient(0, 0, self.width(), self.height())
        c1 = self.ambient_color.darker(140)
        c2 = QColor(18, 18, 18)
        grad.setColorAt(0.0, c1)
        grad.setColorAt(1.0, c2)
        painter.fillRect(self.rect(), grad)
